// sketch.ino — ESP32-S3
// BOOT (GPIO0) -> зелёная матрица
// Клавиатура 4x4 -> выбор списка SSID (одно имя на кнопку, номера 1-20 дописываются автоматически)
// *  -> возобновить спам,  #  -> прекратить спам

#include "USB.h"
#include "USBHIDKeyboard.h"
#include "WiFi.h"
#include "Keypad.h"

USBHIDKeyboard Keyboard;

extern "C" {
#include "esp_wifi.h"
#include <WiFi.h>
#include <Keypad.h>
  esp_err_t esp_wifi_set_channel(uint8_t primary, wifi_second_chan_t second);
  esp_err_t esp_wifi_80211_tx(wifi_interface_t ifx, const void *buffer, int len, bool en_sys_seq);
}

// ===== Keypad 4x4 =====
const byte ROWS = 4;
const byte COLS = 4;

char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};

// R1-R4, C1-C4
byte rowPins[ROWS] = {10, 11, 12, 13};
byte colPins[COLS] = {7, 6, 5, 4};

Keypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);

// ===== Settings =====
const uint8_t channels[] = {1, 6, 11};
const bool wpa2 = true;
const bool appendSpaces = true;
const uint8_t SSIDS_PER_LIST = 20;

// ===== Списки: ОДНА строка на кнопку =====
// В эфир летят "Имя 1" ..."Имя 20", номера добавляются при отправке
const char* listNames[10] = {
  "8Б Хуесосы",
  "8Б Геи",
  "8Б Шлюхи",
  "8Б Педики",
  "8Б Хуйня",
  "8Б Слепые",
  "8Б сосунки",
  "Петя го 1 на 1",
  "Петя хуесос",
  "Бусик ТЦК"
};

// ===== run-time variables =====
char emptySSID[32];
uint8_t channelIndex = 0;
uint8_t macAddr[6];
uint8_t wifi_channel = 1;
uint32_t currentTime = 0;
uint32_t packetSize = 0;
uint32_t packetCounter = 0;
uint32_t attackTime = 0;
uint32_t packetRateTime = 0;

// ===== состояние =====
bool spamActive = false;
uint8_t currentList = 0;

// ===== beacon frame =====
uint8_t beaconPacket[109] = {
  /*  0 -  3 */ 0x80, 0x00, 0x00, 0x00,
  /*  4 -  9 */ 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF,
  /* 10 - 15 */ 0x01, 0x02, 0x03, 0x04, 0x05, 0x06,
  /* 16 - 21 */ 0x01, 0x02, 0x03, 0x04, 0x05, 0x06,

  /* 22 - 23 */ 0x00, 0x00,
  /* 24 - 31 */ 0x83, 0x51, 0xf7, 0x8f, 0x0f, 0x00, 0x00, 0x00,
  /* 32 - 33 */ 0xe8, 0x03,
  /* 34 - 35 */ 0x31, 0x00,

  // SSID
  /* 36 - 37 */ 0x00, 0x20,
  /* 38 - 69 */ 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20,
                0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20,
                0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20,
                0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20, 0x20,

  // Supported Rates
  /* 70 - 71 */ 0x01, 0x08,
  /* 72 - 79 */ 0x82, 0x84, 0x8b, 0x96, 0x24, 0x30, 0x48, 0x6c,

  // Current Channel
  /* 80 - 82 */ 0x03, 0x01, 0x01,

  // RSN (WPA2)
  /* 83 -  84 */ 0x30, 0x18,
  /* 85 -  86 */ 0x01, 0x00,
  /* 87 -  90 */ 0x00, 0x0f, 0xac, 0x02,
  /* 91 -  92 */ 0x02, 0x00,
  /* 93 - 100 */ 0x00, 0x0f, 0xac, 0x04, 0x00, 0x0f, 0xac, 0x04,
  /* 101 - 102 */ 0x01, 0x00,
  /* 103 - 106 */ 0x00, 0x0f, 0xac, 0x02,
  /* 107 - 108 */ 0x00, 0x00
};

void nextChannel() {
  if (sizeof(channels) > 1) {
    uint8_t ch = channels[channelIndex];
    channelIndex++;
    if (channelIndex > sizeof(channels)) channelIndex = 0;

    if (ch != wifi_channel && ch >= 1 && ch <= 14) {
      wifi_channel = ch;
      esp_wifi_set_channel(wifi_channel, WIFI_SECOND_CHAN_NONE);
    }
  }
}

void randomMac() {
  for (int i = 0; i < 6; i++)
    macAddr[i] = random(256);
}

// ===== отправка одного списка =====
// В памяти хранится только базовое имя — номера дописываем здесь
void broadcastList() {
  const char* base = listNames[currentList];
  char ssidBuf[40];

  nextChannel();

  for (uint8_t num = 1; num <= SSIDS_PER_LIST; num++) {
    // собираем "Имя N" одной строкой — никакой пачки строк в прошивке
    snprintf(ssidBuf, sizeof(ssidBuf), "%s %d", base, num);
    uint8_t ssidLen = strlen(ssidBuf);
    if (ssidLen > 32) ssidLen = 32;

    // у каждой сети свой MAC
    macAddr[5] = num;
    memcpy(&beaconPacket[10], macAddr, 6);
    memcpy(&beaconPacket[16], macAddr, 6);

    // канал в кадре
    beaconPacket[82] = wifi_channel;

    if (appendSpaces) {
      // добиваем до 32 байт пробелами — кадр фиксированной длины
      memset(&beaconPacket[38], 0x20, 32);
      memcpy(&beaconPacket[38], ssidBuf, ssidLen);

      for (int k = 0; k < 3; k++) {
        packetCounter += esp_wifi_80211_tx(WIFI_IF_STA, beaconPacket, packetSize, 0) == 0;
        delay(1);
      }
    } else {
      // без padding: обрезаем кадр под реальную длину имени
      uint16_t tmpPacketSize = (109 - 32) + ssidLen;
      uint8_t* tmpPacket = new uint8_t[tmpPacketSize];
      memcpy(&tmpPacket[0], &beaconPacket[0], 37 + ssidLen);
      tmpPacket[37] = ssidLen;
      memcpy(&tmpPacket[38 + ssidLen], &beaconPacket[70], 39);

      for (int k = 0; k < 3; k++) {
        packetCounter += esp_wifi_80211_tx(WIFI_IF_STA, tmpPacket, tmpPacketSize, 0) == 0;
        delay(1);
      }

      delete[] tmpPacket;
    }
  }
}

// ===== матрица по BOOT =====
void runMatrix() {
  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press(KEY_SPACE);
  delay(60);
  Keyboard.releaseAll();
  delay(300);

  Keyboard.press(KEY_LEFT_GUI);
  Keyboard.press('r');
  delay(60);
  Keyboard.releaseAll();
  delay(600);

  Keyboard.print("cmd /k \"color 2&for /l %i in (1,0,2) do @dir /s\"");
  Keyboard.press(KEY_RETURN);
  delay(40);
  Keyboard.releaseAll();
  delay(1500);

  Keyboard.press(KEY_F11);
  delay(50);
  Keyboard.releaseAll();
}

// ===== клавиатура =====
void handleKeypad() {
  char key = keypad.getKey();
  if (!key) return;

  if (key >= '1' && key <= '9') {
    currentList = key - '1';   // '1'->0 ... '9'->8
    spamActive = true;
  } else if (key == '0') {
    currentList = 9;
    spamActive = true;
  } else if (key == '*') {
    spamActive = true;         // возобновить спам
  } else if (key == '#') {
    spamActive = false;        // прекратить спам
  }
  // A/B/C/D — свободные кнопки, повесим что-нибудь потом
}

void setup() {
  randomSeed(1);

  packetSize = sizeof(beaconPacket);
  if (wpa2) {
    beaconPacket[34] = 0x31;
  } else {
    beaconPacket[34] = 0x21;
    packetSize -= 26;
  }

  randomMac();

  pinMode(0, INPUT_PULLUP);

  Keyboard.begin();
  USB.begin();

  WiFi.mode(WIFI_MODE_STA);
  esp_wifi_set_channel(channels[0], WIFI_SECOND_CHAN_NONE);

  delay(3000); // даём ОС опознать HID-клавиатуру
}

void loop() {
  currentTime = millis();

  // клавиатура опрашивается всегда — даже во время спама
  handleKeypad();

  // BOOT -> матрица
  static bool lastBoot = HIGH;
  bool boot = digitalRead(0);
  if (lastBoot == HIGH && boot == LOW) {
    delay(50);
    if (digitalRead(0) == LOW) {
      runMatrix();
      delay(1000);
    }
  }
  lastBoot = boot;

  // рассылка — только пока spamActive
  if (spamActive && currentTime - attackTime > 100) {
    attackTime = currentTime;
    broadcastList();
  }

  // пакеты/сек в Serial (видно только если не USB-OTG)
  if (currentTime - packetRateTime > 1000) {
    packetRateTime = currentTime;
  }
}

